// Scavenger Hunt 2.0 puzzle 2450
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int fold(const vector<int>& values) {
    int state = 0;
    for (size_t i = 0; i < values.size(); ++i) {
        state ^= (values[i] + (int)i * 3) & 127;
        state = ((state << 1) | (state >> 6)) & 127;
    }
    return state;
}

vector<int> undo_scramble(const vector<int>& values, const vector<int>& positions) {
    vector<int> result(values.size(), 0);
    for (size_t original = 0; original < positions.size(); ++original)
        result[original] = values[positions[original]];
    return result;
}

string decode(const vector<int>& values, const vector<int>& positions) {
    vector<int> restored = undo_scramble(values, positions);
    string answer;
    for (size_t i = 0; i < restored.size(); ++i) {
        int value = restored[i];
        value ^= (0x1F + ((int)i % 5));
        value -= 11 + ((int)i % 7);
        answer.push_back((char)value);
    }
    return answer;
}

int main() {
    vector<int> raw = {119, 126, 47, 119, 126, 65, 74, 119, 14, 64, 111, 109, 126, 117};
    vector<int> order = {5, 9, 10, 0, 7, 2, 4, 13, 11, 8, 12, 3, 1, 6};
    const int salt = 9;

    vector<int> masked(raw.size());
    vector<int> noise(raw.size());

    for (size_t i = 0; i < raw.size(); ++i)
        masked[i] = raw[i] ^ ((salt + (int)i) & 31);

    for (size_t i = 0; i < masked.size(); ++i)
        noise[i] = masked[i] ^ ((salt + (int)i) & 31);

    vector<int> shadow(raw.size());
    for (size_t i = 0; i < raw.size(); ++i)
        shadow[i] = ((raw[i] * 7) + 13) % 101;

    int guard = fold(shadow);
    string answer = decode(noise, order);

    if (guard >= 0)
        cout << answer << endl;

    return 0;
}

