#include <vector>
#include <string>
using namespace std;

int fold(const vector<int>& values) {
    int state = 0;
    for (size_t i = 0; i < values.size(); ++i) {
        state ^= (values[i] + (int)i * 3) & 127;
        state = ((state << 1) | (state >> 6)) & 127;
    }
    return state;
}

vector<int> undo_scramble(const vector<int>& values, const vector<int>& positions) {
    vector<int> result(values.size(), 0);
    for (size_t original = 0; original < positions.size(); ++original)
        result[original] = values[positions[original]];
    return result;
}

string decode(const vector<int>& values, const vector<int>& positions) {
    vector<int> restored = undo_scramble(values, positions);
    string answer;
    for (size_t i = 0; i < restored.size(); ++i) {
        int value = restored[i];
        value ^= (0x1F + ((int)i % 5));
        value -= 11 + ((int)i % 7);
        answer.push_back((char)value);
    }
    return answer;
}

